/**
 * WebGCS Connection Manager Module
 * Handles MAVLink connection management and heartbeat monitoring
 */

window.ConnectionManager = (function() {
    'use strict';

    // Private variables
    let heartbeatCount = 0;
    let lastHeartbeatTime = 0;
    let heartbeatInterval = null;
    let isConnecting = false;

    // DOM elements
    let elements = {};

    /**
     * Initialize Connection Manager
     */
    function initialize() {
        console.log('Initializing Connection Manager...');

        // Cache DOM elements
        cacheElements();

        // Setup event listeners
        setupEventListeners();

        // Initialize UI state
        updateConnectionUI(false);

        console.log('Connection Manager initialized');
    }

    /**
     * Cache DOM Elements
     */
    function cacheElements() {
        elements = {
            connectionStatus: document.getElementById('connection-status'),
            heartbeatIndicator: document.getElementById('heartbeat-indicator'),
            heartbeatCounter: document.getElementById('heartbeat-counter'),
            heartbeatSound: document.getElementById('heartbeat-sound'),
            ipAddress: document.getElementById('ip-address'),
            portNumber: document.getElementById('port-number'),
            connectBtn: document.getElementById('connect-btn'),
            disconnectBtn: document.getElementById('disconnect-btn')
        };

        // Check for missing elements
        Object.entries(elements).forEach(([key, element]) => {
            if (!element) {
                console.warn(`Connection Manager: Element '${key}' not found`);
            }
        });
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        // Connect button
        if (elements.connectBtn) {
            elements.connectBtn.addEventListener('click', handleConnect);
        }

        // Disconnect button
        if (elements.disconnectBtn) {
            elements.disconnectBtn.addEventListener('click', handleDisconnect);
        }

        // Input validation
        if (elements.portNumber) {
            elements.portNumber.addEventListener('input', validatePortInput);
        }

        if (elements.ipAddress) {
            elements.ipAddress.addEventListener('input', validateIpInput);
        }

        // Heartbeat sound toggle
        if (elements.heartbeatSound) {
            elements.heartbeatSound.addEventListener('change', handleHeartbeatSoundToggle);
        }

        // Listen for global events
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('websocket_connected', handleWebSocketConnect);
            window.WebGCS.eventBus.addEventListener('websocket_disconnected', handleWebSocketDisconnect);
        }
    }

    /**
     * Handle Connect Button Click
     */
    function handleConnect() {
        if (isConnecting) return;

        const ip = elements.ipAddress?.value?.trim() || '192.168.193.235';
        const port = parseInt(elements.portNumber?.value) || 5678;

        // Validate inputs
        if (!validateIP(ip)) {
            window.WebGCS?.showMessage('Invalid IP address format', 'error');
            return;
        }

        if (port < 1 || port > 65535) {
            window.WebGCS?.showMessage('Port must be between 1 and 65535', 'error');
            return;
        }

        console.log(`Attempting to connect to ${ip}:${port}`);

        // Update UI to connecting state
        setConnectingState(true);

        // Send connection command
        if (window.WebGCS?.sendCommand) {
            const success = window.WebGCS.sendCommand('connect', {
                ip_address: ip,
                port: port
            });

            if (success) {
                window.WebGCS.showMessage(`Connecting to ${ip}:${port}...`, 'info');

                // Set timeout for connection attempt
                setTimeout(() => {
                    if (isConnecting && !window.WebGCS.droneConnected) {
                        setConnectingState(false);
                        window.WebGCS.showMessage('Connection timeout', 'warning');
                    }
                }, 30000); // 30 second timeout
            } else {
                setConnectingState(false);
            }
        } else {
            setConnectingState(false);
            window.WebGCS?.showMessage('WebGCS not ready', 'error');
        }
    }

    /**
     * Handle Disconnect Button Click
     */
    function handleDisconnect() {
        console.log('Disconnecting from drone...');

        // Send disconnect command
        if (window.WebGCS?.sendCommand) {
            window.WebGCS.sendCommand('disconnect');
            window.WebGCS.showMessage('Disconnecting...', 'info');
        }

        // Reset heartbeat
        resetHeartbeat();

        // Update UI
        updateConnectionUI(false);
    }

    /**
     * Set Connecting State
     */
    function setConnectingState(connecting) {
        isConnecting = connecting;

        if (elements.connectBtn) {
            elements.connectBtn.disabled = connecting;
            elements.connectBtn.textContent = connecting ? 'Connecting...' : 'Connect';
        }

        if (elements.disconnectBtn) {
            elements.disconnectBtn.disabled = !connecting && !window.WebGCS?.droneConnected;
        }

        // Update status
        if (elements.connectionStatus && connecting) {
            elements.connectionStatus.className = 'status-indicator connecting';
            elements.connectionStatus.textContent = 'Connecting to drone...';
        }
    }

    /**
     * Update Connection UI
     */
    function updateConnectionUI(connected, systemId = 0) {
        if (elements.connectionStatus) {
            if (connected) {
                elements.connectionStatus.className = 'status-indicator connected';
                elements.connectionStatus.textContent = systemId > 0 
                    ? `Connected to drone (System ${systemId})`
                    : 'Connected to drone';
            } else {
                elements.connectionStatus.className = 'status-indicator disconnected';
                elements.connectionStatus.textContent = 'Disconnected from drone';
            }
        }

        if (elements.connectBtn) {
            elements.connectBtn.disabled = connected || isConnecting;
        }

        if (elements.disconnectBtn) {
            elements.disconnectBtn.disabled = !connected;
        }

        isConnecting = false;
    }

    /**
     * Handle Heartbeat Update
     */
    function updateHeartbeat() {
        heartbeatCount++;
        lastHeartbeatTime = Date.now();

        // Update counter
        if (elements.heartbeatCounter) {
            elements.heartbeatCounter.textContent = heartbeatCount;
        }

        // Animate heartbeat icon
        if (elements.heartbeatIndicator) {
            elements.heartbeatIndicator.classList.add('pulse');
            setTimeout(() => {
                elements.heartbeatIndicator.classList.remove('pulse');
            }, 300);
        }

        // Play heartbeat sound if enabled
        if (elements.heartbeatSound?.checked) {
            playHeartbeatSound();
        }

        // Notify audio manager for voice announcements
        if (window.WebGCS?.modules?.AudioManager?.onHeartbeat) {
            window.WebGCS.modules.AudioManager.onHeartbeat();
        }
    }

    /**
     * Reset Heartbeat
     */
    function resetHeartbeat() {
        heartbeatCount = 0;
        lastHeartbeatTime = 0;

        if (elements.heartbeatCounter) {
            elements.heartbeatCounter.textContent = '0';
        }

        if (heartbeatInterval) {
            clearInterval(heartbeatInterval);
            heartbeatInterval = null;
        }
    }

    /**
     * Play Heartbeat Sound
     */
    function playHeartbeatSound() {
        try {
            // Create audio context if not exists
            if (!window.audioContext) {
                window.audioContext = new (window.AudioContext || window.webkitAudioContext)();
            }

            // Create beep sound
            const oscillator = window.audioContext.createOscillator();
            const gainNode = window.audioContext.createGain();

            oscillator.connect(gainNode);
            gainNode.connect(window.audioContext.destination);

            oscillator.frequency.setValueAtTime(800, window.audioContext.currentTime);
            gainNode.gain.setValueAtTime(0, window.audioContext.currentTime);
            gainNode.gain.linearRampToValueAtTime(0.1, window.audioContext.currentTime + 0.01);
            gainNode.gain.exponentialRampToValueAtTime(0.001, window.audioContext.currentTime + 0.1);

            oscillator.start(window.audioContext.currentTime);
            oscillator.stop(window.audioContext.currentTime + 0.1);

        } catch (error) {
            console.warn('Could not play heartbeat sound:', error);
        }
    }

    /**
     * Validate IP Address
     */
    function validateIP(ip) {
        const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
        return ipRegex.test(ip);
    }

    /**
     * Validate Port Input
     */
    function validatePortInput(event) {
        const port = parseInt(event.target.value);
        if (isNaN(port) || port < 1 || port > 65535) {
            event.target.setCustomValidity('Port must be between 1 and 65535');
        } else {
            event.target.setCustomValidity('');
        }
    }

    /**
     * Validate IP Input
     */
    function validateIpInput(event) {
        const ip = event.target.value.trim();
        if (ip && !validateIP(ip)) {
            event.target.setCustomValidity('Invalid IP address format');
        } else {
            event.target.setCustomValidity('');
        }
    }

    /**
     * Handle Heartbeat Sound Toggle
     */
    function handleHeartbeatSoundToggle(event) {
        const enabled = event.target.checked;
        console.log('Heartbeat sound:', enabled ? 'enabled' : 'disabled');

        // Store preference
        localStorage.setItem('webgcs_heartbeat_sound', enabled.toString());

        if (enabled && window.audioContext?.state === 'suspended') {
            window.audioContext.resume();
        }
    }

    /**
     * Event Handlers
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail;

        // Check for heartbeat (new data received)
        if (data.connected) {
            updateHeartbeat();
        }

        // Update connection status
        updateConnectionUI(data.connected, data.system_id);
    }

    function handleWebSocketConnect() {
        // WebSocket connected - enable connect button if not already connected
        if (elements.connectBtn && !window.WebGCS?.droneConnected) {
            elements.connectBtn.disabled = false;
        }
    }

    function handleWebSocketDisconnect() {
        // WebSocket disconnected - reset everything
        updateConnectionUI(false);
        resetHeartbeat();
        setConnectingState(false);
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,

        // Connection state methods
        isConnected: () => window.WebGCS?.droneConnected || false,
        isConnecting: () => isConnecting,
        getHeartbeatCount: () => heartbeatCount,
        getLastHeartbeatTime: () => lastHeartbeatTime,

        // Module lifecycle callbacks
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: (data) => {
            updateConnectionUI(data.connected);
        },
        onResize: () => {
            // Handle responsive layout changes if needed
        }
    };
})();

// Load saved preferences
document.addEventListener('DOMContentLoaded', function() {
    // Restore heartbeat sound preference
    const heartbeatSoundSaved = localStorage.getItem('webgcs_heartbeat_sound');
    if (heartbeatSoundSaved !== null) {
        const checkbox = document.getElementById('heartbeat-sound');
        if (checkbox) {
            checkbox.checked = heartbeatSoundSaved === 'true';
        }
    }
});

/**
 * WebGCS Flight Controls Module
 * Handles all flight control operations with safety confirmations
 */

window.FlightControls = (function() {
    'use strict';

    // Private variables
    let isConnected = false;
    let currentMode = 'UNKNOWN';
    let isArmed = false;

    // DOM elements
    let elements = {};

    // Safety-critical commands requiring confirmation
    const SAFETY_COMMANDS = ['arm', 'disarm', 'takeoff', 'land', 'rtl'];

    /**
     * Initialize Flight Controls
     */
    function initialize() {
        console.log('Initializing Flight Controls...');

        // Cache DOM elements
        cacheElements();

        // Setup event listeners
        setupEventListeners();

        // Initialize UI state
        updateControlsState();

        console.log('Flight Controls initialized');
    }

    /**
     * Cache DOM Elements
     */
    function cacheElements() {
        elements = {
            armBtn: document.getElementById('arm-btn'),
            disarmBtn: document.getElementById('disarm-btn'),
            takeoffBtn: document.getElementById('takeoff-btn'),
            takeoffAltitude: document.getElementById('takeoff-altitude'),
            landBtn: document.getElementById('land-btn'),
            rtlBtn: document.getElementById('rtl-btn'),
            flightModeSelect: document.getElementById('flight-mode-select'),
            setModeBtn: document.getElementById('set-mode-btn')
        };

        // Check for missing elements
        Object.entries(elements).forEach(([key, element]) => {
            if (!element) {
                console.warn(`Flight Controls: Element '${key}' not found`);
            }
        });
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        // ARM button
        if (elements.armBtn) {
            elements.armBtn.addEventListener('click', () => handleSafetyCommand('arm', 'ARM Vehicle', 'This will ARM the vehicle. Propellers may start spinning!'));
        }

        // DISARM button
        if (elements.disarmBtn) {
            elements.disarmBtn.addEventListener('click', () => handleSafetyCommand('disarm', 'DISARM Vehicle', 'This will DISARM the vehicle. Make sure it is landed safely.'));
        }

        // Takeoff button
        if (elements.takeoffBtn) {
            elements.takeoffBtn.addEventListener('click', handleTakeoff);
        }

        // Land button
        if (elements.landBtn) {
            elements.landBtn.addEventListener('click', () => handleSafetyCommand('land', 'LAND Vehicle', 'This will initiate automatic landing at current position.'));
        }

        // RTL button
        if (elements.rtlBtn) {
            elements.rtlBtn.addEventListener('click', () => handleSafetyCommand('rtl', 'Return to Launch', 'This will return the vehicle to launch position and land.'));
        }

        // Set mode button
        if (elements.setModeBtn) {
            elements.setModeBtn.addEventListener('click', handleSetMode);
        }

        // Takeoff altitude validation
        if (elements.takeoffAltitude) {
            elements.takeoffAltitude.addEventListener('input', validateTakeoffAltitude);
        }

        // Listen for global events
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
            window.WebGCS.eventBus.addEventListener('command_result', handleCommandResult);
        }
    }

    /**
     * Handle Safety Command with Confirmation
     */
    function handleSafetyCommand(command, title, message) {
        if (!isConnected) {
            window.WebGCS?.showMessage('Not connected to drone', 'error');
            return;
        }

        // Show confirmation dialog
        if (window.WebGCS?.showConfirmation) {
            window.WebGCS.showConfirmation(title, message, (confirmed) => {
                if (confirmed) {
                    executeCommand(command);
                } else {
                    window.WebGCS.showMessage(`${command.toUpperCase()} command cancelled`, 'info');
                }
            });
        } else {
            // Fallback if confirmation dialog not available
            if (confirm(`${title}\n\n${message}`)) {
                executeCommand(command);
            }
        }
    }

    /**
     * Handle Takeoff Command
     */
    function handleTakeoff() {
        if (!isConnected) {
            window.WebGCS?.showMessage('Not connected to drone', 'error');
            return;
        }

        if (!isArmed) {
            window.WebGCS?.showMessage('Vehicle must be armed before takeoff', 'warning');
            return;
        }

        const altitude = parseFloat(elements.takeoffAltitude?.value) || 5;

        if (altitude < 1 || altitude > 1000) {
            window.WebGCS?.showMessage('Takeoff altitude must be between 1 and 1000 meters', 'error');
            return;
        }

        const message = `This will initiate takeoff to ${altitude} meters altitude.`;

        if (window.WebGCS?.showConfirmation) {
            window.WebGCS.showConfirmation('TAKEOFF Vehicle', message, (confirmed) => {
                if (confirmed) {
                    executeCommand('takeoff', { altitude: altitude });
                } else {
                    window.WebGCS.showMessage('TAKEOFF command cancelled', 'info');
                }
            });
        } else {
            if (confirm(`TAKEOFF Vehicle\n\n${message}`)) {
                executeCommand('takeoff', { altitude: altitude });
            }
        }
    }

    /**
     * Handle Set Mode Command
     */
    function handleSetMode() {
        if (!isConnected) {
            window.WebGCS?.showMessage('Not connected to drone', 'error');
            return;
        }

        const selectedMode = elements.flightModeSelect?.value;

        if (!selectedMode) {
            window.WebGCS?.showMessage('Please select a flight mode', 'error');
            return;
        }

        if (selectedMode === currentMode) {
            window.WebGCS?.showMessage(`Already in ${selectedMode} mode`, 'info');
            return;
        }

        console.log(`Setting flight mode to: ${selectedMode}`);
        executeCommand('set_mode', { mode: selectedMode });
    }

    /**
     * Execute Command
     */
    function executeCommand(command, params = {}) {
        console.log(`Executing flight command: ${command}`, params);

        // Disable relevant buttons during command execution
        setCommandInProgress(command, true);

        // Send command
        if (window.WebGCS?.sendCommand) {
            const success = window.WebGCS.sendCommand(command, params);
            if (!success) {
                setCommandInProgress(command, false);
            }
        } else {
            window.WebGCS?.showMessage('WebGCS not ready', 'error');
            setCommandInProgress(command, false);
        }
    }

    /**
     * Set Command In Progress State
     */
    function setCommandInProgress(command, inProgress) {
        const buttonMap = {
            'arm': elements.armBtn,
            'disarm': elements.disarmBtn,
            'takeoff': elements.takeoffBtn,
            'land': elements.landBtn,
            'rtl': elements.rtlBtn,
            'set_mode': elements.setModeBtn
        };

        const button = buttonMap[command];
        if (button) {
            button.disabled = inProgress || !isConnected;
            if (inProgress) {
                button.textContent = button.textContent.replace(/\.\.\.$/, '') + '...';
            } else {
                button.textContent = button.textContent.replace(/\.\.\.$/, '');
            }
        }

        // For commands that affect all controls
        if (['arm', 'disarm'].includes(command)) {
            setTimeout(() => updateControlsState(), 1000);
        }
    }

    /**
     * Update Controls State
     */
    function updateControlsState() {
        const buttonsConfig = [
            { element: elements.armBtn, enabled: isConnected && !isArmed },
            { element: elements.disarmBtn, enabled: isConnected && isArmed },
            { element: elements.takeoffBtn, enabled: isConnected && isArmed },
            { element: elements.landBtn, enabled: isConnected },
            { element: elements.rtlBtn, enabled: isConnected },
            { element: elements.setModeBtn, enabled: isConnected }
        ];

        buttonsConfig.forEach(({ element, enabled }) => {
            if (element) {
                element.disabled = !enabled;
            }
        });

        // Update flight mode selector
        if (elements.flightModeSelect) {
            elements.flightModeSelect.disabled = !isConnected;

            // Update current mode selection if it matches
            if (currentMode && currentMode !== 'UNKNOWN') {
                const option = elements.flightModeSelect.querySelector(`option[value="${currentMode}"]`);
                if (option) {
                    elements.flightModeSelect.value = currentMode;
                }
            }
        }
    }

    /**
     * Validate Takeoff Altitude Input
     */
    function validateTakeoffAltitude(event) {
        const altitude = parseFloat(event.target.value);

        if (isNaN(altitude) || altitude < 1 || altitude > 1000) {
            event.target.setCustomValidity('Altitude must be between 1 and 1000 meters');
        } else {
            event.target.setCustomValidity('');
        }

        // Update placeholder if valid
        if (!isNaN(altitude) && altitude >= 1 && altitude <= 1000) {
            event.target.setAttribute('data-valid-alt', altitude);
        }
    }

    /**
     * Event Handlers
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail;

        // Update state
        const wasArmed = isArmed;
        const oldMode = currentMode;

        isArmed = data.armed || false;
        currentMode = data.mode || 'UNKNOWN';

        // Check for state changes
        if (wasArmed !== isArmed) {
            const status = isArmed ? 'ARMED' : 'DISARMED';
            window.WebGCS?.showMessage(`Vehicle ${status}`, isArmed ? 'warning' : 'info');

            // Announce arm/disarm status
            if (window.WebGCS?.modules?.AudioManager?.announceArmStatus) {
                window.WebGCS.modules.AudioManager.announceArmStatus(isArmed);
            }
        }

        if (oldMode !== currentMode && currentMode !== 'UNKNOWN') {
            window.WebGCS?.showMessage(`Flight mode: ${currentMode}`, 'info');

            // Announce mode change
            if (window.WebGCS?.modules?.AudioManager?.announceModeChange) {
                window.WebGCS.modules.AudioManager.announceModeChange(currentMode);
            }
        }

        // Update UI
        updateControlsState();
    }

    function handleConnectionChange(event) {
        isConnected = event.detail.connected;
        updateControlsState();

        // Reset state on disconnect
        if (!isConnected) {
            isArmed = false;
            currentMode = 'UNKNOWN';
        }
    }

    function handleCommandResult(event) {
        const result = event.detail;
        const command = result.command;

        // Re-enable buttons
        setCommandInProgress(command, false);

        // Handle specific command results
        if (result.success) {
            switch (command) {
                case 'arm':
                    window.WebGCS?.showMessage('Vehicle armed successfully', 'success');
                    break;
                case 'disarm':
                    window.WebGCS?.showMessage('Vehicle disarmed successfully', 'success');
                    break;
                case 'takeoff':
                    window.WebGCS?.showMessage('Takeoff command sent successfully', 'success');
                    break;
                case 'land':
                    window.WebGCS?.showMessage('Landing command sent successfully', 'success');
                    break;
                case 'rtl':
                    window.WebGCS?.showMessage('Return to Launch initiated', 'success');
                    break;
                case 'set_mode':
                    window.WebGCS?.showMessage(`Flight mode change to ${result.params?.mode || 'requested mode'} sent`, 'success');
                    break;
            }
        } else {
            // Command failed
            const errorMsg = result.error || 'Unknown error';
            window.WebGCS?.showMessage(`${command.toUpperCase()} failed: ${errorMsg}`, 'error');
        }
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,

        // State getters
        isArmed: () => isArmed,
        getCurrentMode: () => currentMode,
        isConnected: () => isConnected,

        // Module lifecycle callbacks
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: () => {
            // Handle responsive layout changes if needed
        }
    };
})();

/**
 * WebGCS Telemetry Display Module
 * Handles Primary Flight Display (PFD) with attitude indicator and instrument tapes
 */

window.TelemetryDisplay = (function() {
    'use strict';

    // Private variables
    let telemetryData = {};
    let animationFrameId = null;

    // Canvas contexts
    let contexts = {};

    // DOM elements
    let elements = {};

    /**
     * Initialize Telemetry Display
     */
    function initialize() {
        console.log('Initializing Telemetry Display...');

        // Cache DOM elements
        cacheElements();

        // Initialize canvases
        initializeCanvases();

        // Setup event listeners
        setupEventListeners();

        // Start animation loop
        startAnimationLoop();

        console.log('Telemetry Display initialized');
    }

    /**
     * Cache DOM Elements
     */
    function cacheElements() {
        elements = {
            // Canvas elements
            attitudeIndicator: document.getElementById('attitude-indicator'),
            airspeedTape: document.getElementById('airspeed-tape'),
            altitudeTape: document.getElementById('altitude-tape'),

            // Status elements
            armedStatus: document.getElementById('armed-status'),
            flightMode: document.getElementById('flight-mode'),

            // Telemetry elements
            batteryVoltage: document.getElementById('battery-voltage'),
            currentDraw: document.getElementById('current-draw'),
            gpsStatus: document.getElementById('gps-status'),
            positionDisplay: document.getElementById('position-display')
        };

        // Check for missing elements
        Object.entries(elements).forEach(([key, element]) => {
            if (!element) {
                console.warn(`Telemetry Display: Element '${key}' not found`);
            }
        });
    }

    /**
     * Initialize Canvas Contexts
     */
    function initializeCanvases() {
        const canvasElements = ['attitudeIndicator', 'airspeedTape', 'altitudeTape'];

        canvasElements.forEach(name => {
            const canvas = elements[name];
            if (canvas && canvas.getContext) {
                contexts[name] = canvas.getContext('2d');

                // Set high DPI support
                const ctx = contexts[name];
                const dpr = window.devicePixelRatio || 1;
                const rect = canvas.getBoundingClientRect();

                canvas.width = rect.width * dpr;
                canvas.height = rect.height * dpr;
                ctx.scale(dpr, dpr);

                // Set initial styling
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.font = '12px Arial, sans-serif';
            }
        });
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        // Listen for global events
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
        }

        // Handle window resize for canvas scaling
        window.addEventListener('resize', handleResize);
    }

    /**
     * Start Animation Loop
     */
    function startAnimationLoop() {
        function animate() {
            updateAllDisplays();
            animationFrameId = requestAnimationFrame(animate);
        }
        animate();
    }

    /**
     * Update All Displays
     */
    function updateAllDisplays() {
        drawAttitudeIndicator();
        drawAirspeedTape();
        drawAltitudeTape();
        updateTextualDisplays();
    }

    /**
     * Draw Attitude Indicator (Artificial Horizon)
     */
    function drawAttitudeIndicator() {
        const ctx = contexts.attitudeIndicator;
        if (!ctx) return;

        const canvas = elements.attitudeIndicator;
        const width = canvas.clientWidth;
        const height = canvas.clientHeight;
        const centerX = width / 2;
        const centerY = height / 2;
        const radius = Math.min(width, height) / 2 - 10;

        // Clear canvas
        ctx.clearRect(0, 0, width, height);

        // Get attitude data
        const pitch = telemetryData.pitch || 0; // In degrees
        const roll = telemetryData.roll || 0;   // In degrees

        // Save context
        ctx.save();

        // Translate to center
        ctx.translate(centerX, centerY);

        // Draw horizon background
        ctx.save();

        // Rotate by roll angle
        ctx.rotate(roll * Math.PI / 180);

        // Create clipping circle
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.clip();

        // Calculate pitch offset
        const pitchPixels = pitch * 3; // 3 pixels per degree

        // Draw sky (upper half)
        ctx.fillStyle = '#87CEEB';
        ctx.fillRect(-radius, -radius, radius * 2, radius + pitchPixels);

        // Draw ground (lower half)
        ctx.fillStyle = '#8B4513';
        ctx.fillRect(-radius, pitchPixels, radius * 2, radius * 2);

        // Draw horizon line
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(-radius, pitchPixels);
        ctx.lineTo(radius, pitchPixels);
        ctx.stroke();

        // Draw pitch lines
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 1;
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillStyle = '#FFFFFF';

        for (let angle = -90; angle <= 90; angle += 10) {
            if (angle === 0) continue; // Skip horizon line

            const y = pitchPixels - (angle * 3);
            const lineLength = angle % 30 === 0 ? 40 : 20;

            if (Math.abs(y) < radius) {
                // Draw line
                ctx.beginPath();
                ctx.moveTo(-lineLength / 2, y);
                ctx.lineTo(lineLength / 2, y);
                ctx.stroke();

                // Draw angle text for major lines
                if (angle % 30 === 0) {
                    ctx.fillText(Math.abs(angle).toString(), -lineLength / 2 - 15, y);
                    ctx.fillText(Math.abs(angle).toString(), lineLength / 2 + 15, y);
                }
            }
        }

        ctx.restore();

        // Draw aircraft symbol (fixed in center)
        ctx.strokeStyle = '#FFFF00';
        ctx.lineWidth = 3;
        ctx.beginPath();
        // Center dot
        ctx.beginPath();
        ctx.arc(0, 0, 3, 0, Math.PI * 2);
        ctx.fill();
        // Wings
        ctx.moveTo(-30, 0);
        ctx.lineTo(-10, 0);
        ctx.moveTo(10, 0);
        ctx.lineTo(30, 0);
        ctx.moveTo(0, -10);
        ctx.lineTo(0, 10);
        ctx.stroke();

        // Draw outer circle
        ctx.strokeStyle = '#333333';
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(0, 0, radius, 0, Math.PI * 2);
        ctx.stroke();

        // Draw roll scale
        drawRollScale(ctx, radius);

        ctx.restore();
    }

    /**
     * Draw Roll Scale
     */
    function drawRollScale(ctx, radius) {
        const roll = telemetryData.roll || 0;

        // Draw roll marks
        ctx.strokeStyle = '#333333';
        ctx.lineWidth = 2;

        const marks = [-60, -45, -30, -20, -10, 0, 10, 20, 30, 45, 60];
        marks.forEach(angle => {
            const radian = (angle - 90) * Math.PI / 180;
            const x1 = Math.cos(radian) * (radius - 10);
            const y1 = Math.sin(radian) * (radius - 10);
            const x2 = Math.cos(radian) * (radius + 5);
            const y2 = Math.sin(radian) * (radius + 5);

            ctx.beginPath();
            ctx.moveTo(x1, y1);
            ctx.lineTo(x2, y2);
            ctx.stroke();

            if ([0, 30, 60].includes(Math.abs(angle))) {
                ctx.font = '10px Arial';
                ctx.textAlign = 'center';
                ctx.fillStyle = '#333333';
                const textX = Math.cos(radian) * (radius + 15);
                const textY = Math.sin(radian) * (radius + 15);
                ctx.fillText(Math.abs(angle).toString(), textX, textY);
            }
        });

        // Draw roll indicator triangle
        ctx.fillStyle = '#FF0000';
        ctx.beginPath();
        ctx.moveTo(0, -radius - 10);
        ctx.lineTo(-5, -radius);
        ctx.lineTo(5, -radius);
        ctx.closePath();
        ctx.fill();
    }

    /**
     * Draw Airspeed Tape
     */
    function drawAirspeedTape() {
        const ctx = contexts.airspeedTape;
        if (!ctx) return;

        const canvas = elements.airspeedTape;
        const width = canvas.clientWidth;
        const height = canvas.clientHeight;

        // Clear canvas
        ctx.clearRect(0, 0, width, height);

        // Get airspeed data
        const airspeed = Math.sqrt(
            Math.pow(telemetryData.vx || 0, 2) + 
            Math.pow(telemetryData.vy || 0, 2)
        ); // Ground speed as proxy for airspeed

        // Draw tape background
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, width, height);

        // Draw speed marks
        const centerY = height / 2;
        const pixelsPerUnit = 5; // 5 pixels per m/s

        ctx.strokeStyle = '#FFFFFF';
        ctx.fillStyle = '#FFFFFF';
        ctx.lineWidth = 1;
        ctx.font = '12px Arial';
        ctx.textAlign = 'right';

        // Draw speed scale
        const minSpeed = Math.max(0, airspeed - 20);
        const maxSpeed = airspeed + 20;

        for (let speed = Math.floor(minSpeed); speed <= maxSpeed; speed++) {
            const y = centerY - (speed - airspeed) * pixelsPerUnit;

            if (y >= 0 && y <= height) {
                // Major marks every 5 m/s
                if (speed % 5 === 0) {
                    ctx.beginPath();
                    ctx.moveTo(width - 15, y);
                    ctx.lineTo(width, y);
                    ctx.stroke();

                    ctx.fillText(speed.toString(), width - 20, y + 3);
                } else {
                    // Minor marks
                    ctx.beginPath();
                    ctx.moveTo(width - 8, y);
                    ctx.lineTo(width, y);
                    ctx.stroke();
                }
            }
        }

        // Draw current speed box
        ctx.fillStyle = '#000000';
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 2;

        const boxWidth = 35;
        const boxHeight = 20;
        const boxX = width - boxWidth;
        const boxY = centerY - boxHeight / 2;

        ctx.fillRect(boxX, boxY, boxWidth, boxHeight);
        ctx.strokeRect(boxX, boxY, boxWidth, boxHeight);

        // Draw speed text
        ctx.fillStyle = '#FFFFFF';
        ctx.textAlign = 'center';
        ctx.font = '14px Arial';
        ctx.fillText(airspeed.toFixed(1), boxX + boxWidth / 2, centerY + 3);
    }

    /**
     * Draw Altitude Tape
     */
    function drawAltitudeTape() {
        const ctx = contexts.altitudeTape;
        if (!ctx) return;

        const canvas = elements.altitudeTape;
        const width = canvas.clientWidth;
        const height = canvas.clientHeight;

        // Clear canvas
        ctx.clearRect(0, 0, width, height);

        // Get altitude data
        const altitude = telemetryData.alt_rel || 0;

        // Draw tape background
        ctx.fillStyle = '#000000';
        ctx.fillRect(0, 0, width, height);

        // Draw altitude marks
        const centerY = height / 2;
        const pixelsPerUnit = 2; // 2 pixels per meter

        ctx.strokeStyle = '#FFFFFF';
        ctx.fillStyle = '#FFFFFF';
        ctx.lineWidth = 1;
        ctx.font = '12px Arial';
        ctx.textAlign = 'left';

        // Draw altitude scale
        const minAlt = altitude - 50;
        const maxAlt = altitude + 50;

        for (let alt = Math.floor(minAlt / 10) * 10; alt <= maxAlt; alt += 10) {
            const y = centerY - (alt - altitude) * pixelsPerUnit;

            if (y >= 0 && y <= height) {
                // Major marks every 10m
                ctx.beginPath();
                ctx.moveTo(0, y);
                ctx.lineTo(15, y);
                ctx.stroke();

                ctx.fillText(alt.toString(), 20, y + 3);

                // Minor marks every 5m
                const y5 = centerY - (alt + 5 - altitude) * pixelsPerUnit;
                if (y5 >= 0 && y5 <= height) {
                    ctx.beginPath();
                    ctx.moveTo(0, y5);
                    ctx.lineTo(8, y5);
                    ctx.stroke();
                }
            }
        }

        // Draw current altitude box
        ctx.fillStyle = '#000000';
        ctx.strokeStyle = '#FFFFFF';
        ctx.lineWidth = 2;

        const boxWidth = 45;
        const boxHeight = 20;
        const boxX = 0;
        const boxY = centerY - boxHeight / 2;

        ctx.fillRect(boxX, boxY, boxWidth, boxHeight);
        ctx.strokeRect(boxX, boxY, boxWidth, boxHeight);

        // Draw altitude text
        ctx.fillStyle = '#FFFFFF';
        ctx.textAlign = 'center';
        ctx.font = '14px Arial';
        ctx.fillText(altitude.toFixed(1), boxX + boxWidth / 2, centerY + 3);
    }

    /**
     * Update Textual Displays
     */
    function updateTextualDisplays() {
        // Armed status
        if (elements.armedStatus) {
            const armed = telemetryData.armed;
            elements.armedStatus.textContent = armed ? 'ARMED' : 'DISARMED';
            elements.armedStatus.className = `armed-status ${armed ? 'armed' : ''}`;
        }

        // Flight mode
        if (elements.flightMode) {
            const mode = telemetryData.mode || 'UNKNOWN';
            elements.flightMode.textContent = `Mode: ${mode}`;
        }

        // Battery voltage
        if (elements.batteryVoltage) {
            const voltage = telemetryData.battery_voltage || 0;
            elements.batteryVoltage.textContent = `Bat: ${voltage.toFixed(1)} V`;
        }

        // Current draw
        if (elements.currentDraw) {
            const current = telemetryData.current || 0;
            elements.currentDraw.textContent = `Cur: ${current.toFixed(1)} A`;
        }

        // GPS status
        if (elements.gpsStatus) {
            const fixType = telemetryData.gps_fix_type || 0;
            const sats = telemetryData.satellites_visible || 0;
            const hdop = telemetryData.hdop || 99.9;

            const fixTypes = ['NO_GPS', 'NO_FIX', '2D_FIX', '3D_FIX', 'DGPS', 'RTK_FLOAT', 'RTK_FIXED'];
            const fixName = fixTypes[fixType] || 'UNKNOWN';

            elements.gpsStatus.textContent = `GPS: ${fixName} (${sats}) HDOP:${hdop.toFixed(1)}`;
        }

        // Position display
        if (elements.positionDisplay) {
            const lat = telemetryData.lat || 0;
            const lon = telemetryData.lon || 0;
            elements.positionDisplay.textContent = `${lat.toFixed(6)}, ${lon.toFixed(6)}`;
        }
    }

    /**
     * Handle Window Resize
     */
    function handleResize() {
        // Reinitialize canvases with new dimensions
        setTimeout(() => {
            initializeCanvases();
        }, 100);
    }

    /**
     * Event Handlers
     */
    function handleTelemetryUpdate(event) {
        telemetryData = { ...telemetryData, ...event.detail };
    }

    function handleConnectionChange(event) {
        if (!event.detail.connected) {
            // Reset data on disconnect
            telemetryData = {};
        }
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,

        // Data getters
        getTelemetryData: () => ({ ...telemetryData }),

        // Module lifecycle callbacks
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: handleResize,

        // Cleanup
        destroy: () => {
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
            }
        }
    };
})();

/**
 * WebGCS Navigation Controls Module
 * Handles coordinate-based navigation and Go To commands
 */

window.NavigationControls = (function() {
    'use strict';

    // Private variables
    let isConnected = false;
    let currentPosition = { lat: 0, lon: 0, alt: 0 };

    // DOM elements
    let elements = {};

    /**
     * Initialize Navigation Controls
     */
    function initialize() {
        console.log('Initializing Navigation Controls...');

        // Cache DOM elements
        cacheElements();

        // Setup event listeners
        setupEventListeners();

        // Initialize UI state
        updateControlsState();

        console.log('Navigation Controls initialized');
    }

    /**
     * Cache DOM Elements
     */
    function cacheElements() {
        elements = {
            navLat: document.getElementById('nav-lat'),
            navLon: document.getElementById('nav-lon'),
            navAlt: document.getElementById('nav-alt'),
            gotoBtn: document.getElementById('goto-btn'),
            clearNavBtn: document.getElementById('clear-nav-btn'),
            requestFenceBtn: document.getElementById('request-fence-btn'),
            requestMissionBtn: document.getElementById('request-mission-btn')
        };

        // Check for missing elements
        Object.entries(elements).forEach(([key, element]) => {
            if (!element) {
                console.warn(`Navigation Controls: Element '${key}' not found`);
            }
        });
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        // Go To button
        if (elements.gotoBtn) {
            elements.gotoBtn.addEventListener('click', handleGoTo);
        }

        // Clear navigation button
        if (elements.clearNavBtn) {
            elements.clearNavBtn.addEventListener('click', handleClearNav);
        }

        // Request buttons
        if (elements.requestFenceBtn) {
            elements.requestFenceBtn.addEventListener('click', handleRequestFence);
        }

        if (elements.requestMissionBtn) {
            elements.requestMissionBtn.addEventListener('click', handleRequestMission);
        }

        // Input validation
        if (elements.navLat) {
            elements.navLat.addEventListener('input', validateLatitudeInput);
            elements.navLat.addEventListener('blur', formatLatitudeInput);
        }

        if (elements.navLon) {
            elements.navLon.addEventListener('input', validateLongitudeInput);
            elements.navLon.addEventListener('blur', formatLongitudeInput);
        }

        if (elements.navAlt) {
            elements.navAlt.addEventListener('input', validateAltitudeInput);
        }

        // Listen for global events
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
            window.WebGCS.eventBus.addEventListener('command_result', handleCommandResult);
        }

        // Listen for map click events (for fly-to functionality)
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('map_clicked', handleMapClick);
        }
    }

    /**
     * Handle Go To Command
     */
    function handleGoTo() {
        if (!isConnected) {
            window.WebGCS?.showMessage('Not connected to drone', 'error');
            return;
        }

        // Get and validate coordinates
        const coords = getNavigationCoordinates();
        if (!coords) return;

        // Confirm navigation command
        const message = `Navigate to:\nLat: ${coords.lat.toFixed(6)}\nLon: ${coords.lon.toFixed(6)}\nAlt: ${coords.alt}m AGL`;

        if (window.WebGCS?.showConfirmation) {
            window.WebGCS.showConfirmation('Navigate to Coordinates', message, (confirmed) => {
                if (confirmed) {
                    executeGoToCommand(coords);
                } else {
                    window.WebGCS.showMessage('Navigation command cancelled', 'info');
                }
            });
        } else {
            if (confirm(`Navigate to Coordinates\n\n${message}`)) {
                executeGoToCommand(coords);
            }
        }
    }

    /**
     * Execute Go To Command
     */
    function executeGoToCommand(coords) {
        console.log('Executing Go To command:', coords);

        // Disable button during command execution
        if (elements.gotoBtn) {
            elements.gotoBtn.disabled = true;
            elements.gotoBtn.textContent = 'Sending...';
        }

        // Send goto command
        if (window.WebGCS?.sendCommand) {
            window.WebGCS.sendCommand('goto', {
                lat: coords.lat,
                lon: coords.lon,
                alt: coords.alt
            });
        }

        // Update map target if map controller exists
        if (window.WebGCS?.modules?.MapController?.setTarget) {
            window.WebGCS.modules.MapController.setTarget(coords.lat, coords.lon);
        }

        // Show progress message
        window.WebGCS?.showMessage(`Navigating to ${coords.lat.toFixed(6)}, ${coords.lon.toFixed(6)}`, 'info');
    }

    /**
     * Handle Clear Navigation
     */
    function handleClearNav() {
        if (elements.navLat) elements.navLat.value = '';
        if (elements.navLon) elements.navLon.value = '';
        if (elements.navAlt) elements.navAlt.value = '10';

        // Clear map target
        if (window.WebGCS?.modules?.MapController?.clearTarget) {
            window.WebGCS.modules.MapController.clearTarget();
        }

        window.WebGCS?.showMessage('Navigation inputs cleared', 'info');
    }

    /**
     * Handle Request Fence
     */
    function handleRequestFence() {
        if (!isConnected) {
            window.WebGCS?.showMessage('Not connected to drone', 'error');
            return;
        }

        console.log('Requesting geofence from vehicle...');

        // Disable button during request
        if (elements.requestFenceBtn) {
            elements.requestFenceBtn.disabled = true;
            elements.requestFenceBtn.textContent = 'Requesting...';
        }

        // Send request fence command
        if (window.WebGCS?.sendCommand) {
            window.WebGCS.sendCommand('request_fence');
        }

        window.WebGCS?.showMessage('Requesting geofence data...', 'info');
    }

    /**
     * Handle Request Mission
     */
    function handleRequestMission() {
        if (!isConnected) {
            window.WebGCS?.showMessage('Not connected to drone', 'error');
            return;
        }

        console.log('Requesting mission from vehicle...');

        // Disable button during request
        if (elements.requestMissionBtn) {
            elements.requestMissionBtn.disabled = true;
            elements.requestMissionBtn.textContent = 'Requesting...';
        }

        // Send request mission command
        if (window.WebGCS?.sendCommand) {
            window.WebGCS.sendCommand('request_mission');
        }

        window.WebGCS?.showMessage('Requesting mission data...', 'info');
    }

    /**
     * Get and Validate Navigation Coordinates
     */
    function getNavigationCoordinates() {
        const latStr = elements.navLat?.value?.trim();
        const lonStr = elements.navLon?.value?.trim();
        const altStr = elements.navAlt?.value?.trim() || '10';

        // Check if coordinates are provided
        if (!latStr || !lonStr) {
            window.WebGCS?.showMessage('Please enter latitude and longitude coordinates', 'error');
            return null;
        }

        // Parse and validate coordinates
        const lat = parseFloat(latStr);
        const lon = parseFloat(lonStr);
        const alt = parseFloat(altStr);

        // Validate latitude
        if (isNaN(lat) || lat < -90 || lat > 90) {
            window.WebGCS?.showMessage('Latitude must be between -90 and 90 degrees', 'error');
            elements.navLat?.focus();
            return null;
        }

        // Validate longitude
        if (isNaN(lon) || lon < -180 || lon > 180) {
            window.WebGCS?.showMessage('Longitude must be between -180 and 180 degrees', 'error');
            elements.navLon?.focus();
            return null;
        }

        // Validate altitude
        if (isNaN(alt) || alt < -100 || alt > 5000) {
            window.WebGCS?.showMessage('Altitude must be between -100 and 5000 meters', 'error');
            elements.navAlt?.focus();
            return null;
        }

        return { lat, lon, alt };
    }

    /**
     * Input Validation Functions
     */
    function validateLatitudeInput(event) {
        const lat = parseFloat(event.target.value);
        if (event.target.value && (isNaN(lat) || lat < -90 || lat > 90)) {
            event.target.setCustomValidity('Latitude must be between -90 and 90 degrees');
        } else {
            event.target.setCustomValidity('');
        }
    }

    function validateLongitudeInput(event) {
        const lon = parseFloat(event.target.value);
        if (event.target.value && (isNaN(lon) || lon < -180 || lon > 180)) {
            event.target.setCustomValidity('Longitude must be between -180 and 180 degrees');
        } else {
            event.target.setCustomValidity('');
        }
    }

    function validateAltitudeInput(event) {
        const alt = parseFloat(event.target.value);
        if (event.target.value && (isNaN(alt) || alt < -100 || alt > 5000)) {
            event.target.setCustomValidity('Altitude must be between -100 and 5000 meters');
        } else {
            event.target.setCustomValidity('');
        }
    }

    function formatLatitudeInput(event) {
        const lat = parseFloat(event.target.value);
        if (!isNaN(lat) && lat >= -90 && lat <= 90) {
            event.target.value = lat.toFixed(6);
        }
    }

    function formatLongitudeInput(event) {
        const lon = parseFloat(event.target.value);
        if (!isNaN(lon) && lon >= -180 && lon <= 180) {
            event.target.value = lon.toFixed(6);
        }
    }

    /**
     * Update Controls State
     */
    function updateControlsState() {
        const buttonsConfig = [
            { element: elements.gotoBtn, enabled: isConnected },
            { element: elements.clearNavBtn, enabled: true },
            { element: elements.requestFenceBtn, enabled: isConnected },
            { element: elements.requestMissionBtn, enabled: isConnected }
        ];

        buttonsConfig.forEach(({ element, enabled }) => {
            if (element && !element.textContent.includes('...')) {
                element.disabled = !enabled;
            }
        });

        // Enable/disable inputs
        const inputs = [elements.navLat, elements.navLon, elements.navAlt];
        inputs.forEach(input => {
            if (input) {
                input.disabled = false; // Navigation inputs always enabled
            }
        });
    }

    /**
     * Set Coordinates from External Source
     */
    function setCoordinates(lat, lon, alt = null) {
        if (elements.navLat) {
            elements.navLat.value = lat.toFixed(6);
        }
        if (elements.navLon) {
            elements.navLon.value = lon.toFixed(6);
        }
        if (alt !== null && elements.navAlt) {
            elements.navAlt.value = alt.toString();
        }

        console.log(`Navigation coordinates set to: ${lat.toFixed(6)}, ${lon.toFixed(6)}`);
    }

    /**
     * Event Handlers
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail;
        currentPosition = {
            lat: data.lat || 0,
            lon: data.lon || 0,
            alt: data.alt_rel || 0
        };
    }

    function handleConnectionChange(event) {
        isConnected = event.detail.connected;
        updateControlsState();
    }

    function handleCommandResult(event) {
        const result = event.detail;
        const command = result.command;

        // Re-enable buttons after command completion
        if (command === 'goto' && elements.gotoBtn) {
            elements.gotoBtn.disabled = !isConnected;
            elements.gotoBtn.textContent = 'Go To';
        }

        if (command === 'request_fence' && elements.requestFenceBtn) {
            elements.requestFenceBtn.disabled = !isConnected;
            elements.requestFenceBtn.textContent = 'Request Fence';

            if (result.success) {
                window.WebGCS?.showMessage('Geofence data received', 'success');
                // TODO: Display fence data on map
            } else {
                window.WebGCS?.showMessage(`Fence request failed: ${result.error}`, 'error');
            }
        }

        if (command === 'request_mission' && elements.requestMissionBtn) {
            elements.requestMissionBtn.disabled = !isConnected;
            elements.requestMissionBtn.textContent = 'Request Mission';

            if (result.success) {
                window.WebGCS?.showMessage('Mission data received', 'success');
                // TODO: Display mission waypoints on map
            } else {
                window.WebGCS?.showMessage(`Mission request failed: ${result.error}`, 'error');
            }
        }

        if (command === 'goto') {
            if (result.success) {
                window.WebGCS?.showMessage('Go To command sent successfully', 'success');
            } else {
                window.WebGCS?.showMessage(`Go To failed: ${result.error}`, 'error');
            }
        }
    }

    function handleMapClick(event) {
        const { lat, lon } = event.detail;

        // Check if fly-to mode is active
        if (window.WebGCS?.modules?.MapController?.isFlyToActive?.()) {
            setCoordinates(lat, lon);
            window.WebGCS?.showMessage(`Coordinates set from map: ${lat.toFixed(6)}, ${lon.toFixed(6)}`, 'info');
        }
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,

        // Coordinate management
        setCoordinates: setCoordinates,
        getCoordinates: getNavigationCoordinates,
        getCurrentPosition: () => ({ ...currentPosition }),

        // State getters
        isConnected: () => isConnected,

        // Module lifecycle callbacks
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: () => {
            // Handle responsive layout changes if needed
        }
    };
})();

/**
 * WebGCS Map Controller Module
 * Handles Leaflet map integration with drone positioning and click-to-fly
 */

window.MapController = (function() {
    'use strict';

    // Private variables
    let map = null;
    let markers = {};
    let layers = {};
    let flyToMode = false;
    let isConnected = false;
    let currentPosition = { lat: 0, lon: 0 };
    let homePosition = { lat: 0, lon: 0 };

    // DOM elements
    let elements = {};

    // Map configuration
    const MAP_CONFIG = {
        defaultCenter: [37.7749, -122.4194], // San Francisco
        defaultZoom: 10,
        minZoom: 2,
        maxZoom: 22
    };

    /**
     * Initialize Map Controller
     */
    function initialize() {
        console.log('Initializing Map Controller...');

        // Cache DOM elements
        cacheElements();

        // Initialize map
        initializeMap();

        // Setup event listeners
        setupEventListeners();

        // Initialize UI state
        updateControlsState();

        console.log('Map Controller initialized');
    }

    /**
     * Cache DOM Elements
     */
    function cacheElements() {
        elements = {
            mapDiv: document.getElementById('map'),
            centerMapBtn: document.getElementById('center-map-btn'),
            flyToToggle: document.getElementById('fly-to-toggle'),
            offlineMapsToggle: document.getElementById('offline-maps-toggle')
        };

        // Check for missing elements
        Object.entries(elements).forEach(([key, element]) => {
            if (!element) {
                console.warn(`Map Controller: Element '${key}' not found`);
            }
        });
    }

    /**
     * Initialize Leaflet Map
     */
    function initializeMap() {
        if (!elements.mapDiv) {
            console.error('Map container not found');
            return;
        }

        try {
            // Create map instance
            map = L.map(elements.mapDiv, {
                center: MAP_CONFIG.defaultCenter,
                zoom: MAP_CONFIG.defaultZoom,
                minZoom: MAP_CONFIG.minZoom,
                maxZoom: MAP_CONFIG.maxZoom,
                zoomControl: true
            });

            // Add base layers
            addBaseLayers();

            // Add layer control
            addLayerControl();

            // Initialize markers
            initializeMarkers();

            // Setup map event listeners
            setupMapEvents();

            console.log('Leaflet map initialized');
        } catch (error) {
            console.error('Failed to initialize map:', error);
            if (elements.mapDiv) {
                elements.mapDiv.innerHTML = '<div style="padding: 20px; text-align: center; color: #666;">Map initialization failed</div>';
            }
        }
    }

    /**
     * Add Base Map Layers
     */
    function addBaseLayers() {
        // OpenStreetMap layer
        layers.street = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
            attribution: '© OpenStreetMap contributors',
            maxZoom: 19
        });

        // Satellite layer (Esri World Imagery)
        layers.satellite = L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}', {
            attribution: '© Esri, Maxar, GeoEye, Earthstar Geographics, CNES/Airbus DS, USDA, USGS, AeroGRID, IGN, and the GIS User Community',
            maxZoom: 19
        });

        // Add default layer
        layers.street.addTo(map);
    }

    /**
     * Add Layer Control
     */
    function addLayerControl() {
        const baseLayers = {
            "Street Map": layers.street,
            "Satellite": layers.satellite
        };

        const layerControl = L.control.layers(baseLayers, null, {
            position: 'topleft',
            collapsed: false
        });

        layerControl.addTo(map);
    }

    /**
     * Initialize Map Markers
     */
    function initializeMarkers() {
        // Drone marker (blue arrow)
        const droneIcon = L.divIcon({
            html: '<div style="transform: rotate(0deg); color: #007bff; font-size: 24px;">▲</div>',
            className: 'drone-marker',
            iconSize: [24, 24],
            iconAnchor: [12, 12]
        });

        markers.drone = L.marker(MAP_CONFIG.defaultCenter, { 
            icon: droneIcon,
            title: 'Drone Position'
        });

        // Home marker (green house)
        const homeIcon = L.divIcon({
            html: '<div style="color: #28a745; font-size: 20px;">🏠</div>',
            className: 'home-marker',
            iconSize: [20, 20],
            iconAnchor: [10, 10]
        });

        markers.home = L.marker(MAP_CONFIG.defaultCenter, {
            icon: homeIcon,
            title: 'Home Position'
        });

        // Target marker (red bullseye with pulse animation)
        const targetIcon = L.divIcon({
            html: '<div style="color: #dc3545; font-size: 20px;" class="pulse-animation">🎯</div>',
            className: 'target-marker',
            iconSize: [20, 20],
            iconAnchor: [10, 10]
        });

        markers.target = L.marker(MAP_CONFIG.defaultCenter, {
            icon: targetIcon,
            title: 'Navigation Target'
        });

        // Add CSS for pulse animation
        addPulseAnimation();
    }

    /**
     * Add Pulse Animation CSS
     */
    function addPulseAnimation() {
        if (!document.getElementById('map-animations')) {
            const style = document.createElement('style');
            style.id = 'map-animations';
            style.textContent = `
                @keyframes pulse {
                    0% { transform: scale(1); opacity: 1; }
                    50% { transform: scale(1.2); opacity: 0.7; }
                    100% { transform: scale(1); opacity: 1; }
                }
                .pulse-animation {
                    animation: pulse 2s infinite;
                }
                .drone-marker {
                    transition: transform 0.3s ease;
                }
            `;
            document.head.appendChild(style);
        }
    }

    /**
     * Setup Map Event Listeners
     */
    function setupMapEvents() {
        if (!map) return;

        // Map click event
        map.on('click', handleMapClick);

        // Map move events for updating offline maps area
        map.on('moveend zoomend', handleMapViewChange);
    }

    /**
     * Setup UI Event Listeners
     */
    function setupEventListeners() {
        // Center map button
        if (elements.centerMapBtn) {
            elements.centerMapBtn.addEventListener('click', centerMap);
        }

        // Fly to toggle button
        if (elements.flyToToggle) {
            elements.flyToToggle.addEventListener('click', toggleFlyToMode);
        }

        // Offline maps toggle button
        if (elements.offlineMapsToggle) {
            elements.offlineMapsToggle.addEventListener('click', toggleOfflineMapsPanel);
        }

        // Listen for global events
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
        }
    }

    /**
     * Handle Map Click
     */
    function handleMapClick(event) {
        const { lat, lng } = event.latlng;

        console.log(`Map clicked at: ${lat.toFixed(6)}, ${lng.toFixed(6)}`);

        // Emit map click event for other modules
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.dispatchEvent(new CustomEvent('map_clicked', {
                detail: { lat, lon: lng }
            }));
        }

        // Handle fly-to mode
        if (flyToMode) {
            setTarget(lat, lng);

            // Auto-execute navigation if connected
            if (isConnected && window.WebGCS?.modules?.NavigationControls?.setCoordinates) {
                window.WebGCS.modules.NavigationControls.setCoordinates(lat, lng);
                window.WebGCS?.showMessage(`Target set: ${lat.toFixed(6)}, ${lng.toFixed(6)}`, 'info');
            }
        }
    }

    /**
     * Handle Map View Change
     */
    function handleMapViewChange() {
        // Update offline maps area if panel is open
        if (window.WebGCS?.modules?.OfflineMaps?.updateCurrentMapView) {
            window.WebGCS.modules.OfflineMaps.updateCurrentMapView(map.getBounds(), map.getZoom());
        }
    }

    /**
     * Center Map on Drone
     */
    function centerMap() {
        if (!map) return;

        if (isConnected && currentPosition.lat !== 0 && currentPosition.lon !== 0) {
            map.setView([currentPosition.lat, currentPosition.lon], map.getZoom());
            window.WebGCS?.showMessage('Map centered on drone', 'info');
        } else {
            window.WebGCS?.showMessage('No drone position available', 'warning');
        }
    }

    /**
     * Toggle Fly-To Mode
     */
    function toggleFlyToMode() {
        flyToMode = !flyToMode;

        if (elements.flyToToggle) {
            elements.flyToToggle.setAttribute('data-active', flyToMode.toString());
            elements.flyToToggle.textContent = flyToMode ? 'Fly To: ON' : 'Fly To: OFF';
            elements.flyToToggle.className = flyToMode 
                ? 'btn btn-success' 
                : 'btn btn-secondary';
        }

        // Update map cursor
        if (map && elements.mapDiv) {
            elements.mapDiv.style.cursor = flyToMode ? 'crosshair' : '';
        }

        const status = flyToMode ? 'enabled' : 'disabled';
        window.WebGCS?.showMessage(`Fly-to mode ${status}`, 'info');

        console.log('Fly-to mode:', flyToMode);
    }

    /**
     * Toggle Offline Maps Panel
     */
    function toggleOfflineMapsPanel() {
        const panel = document.getElementById('offline-maps-panel');
        if (panel) {
            panel.classList.toggle('active');
        }
    }

    /**
     * Update Drone Position
     */
    function updateDronePosition(lat, lon, heading = 0) {
        if (!map || !markers.drone) return;

        currentPosition = { lat, lon };

        // Update marker position
        markers.drone.setLatLng([lat, lon]);

        // Update drone icon rotation based on heading
        const droneIcon = L.divIcon({
            html: `<div style="transform: rotate(${heading}deg); color: #007bff; font-size: 24px;">▲</div>`,
            className: 'drone-marker',
            iconSize: [24, 24],
            iconAnchor: [12, 12]
        });
        markers.drone.setIcon(droneIcon);

        // Add to map if not already added
        if (!map.hasLayer(markers.drone)) {
            markers.drone.addTo(map);
        }

        // Update tooltip
        markers.drone.setTooltip(`Drone: ${lat.toFixed(6)}, ${lon.toFixed(6)}<br>Heading: ${heading.toFixed(1)}°`);
    }

    /**
     * Update Home Position
     */
    function updateHomePosition(lat, lon) {
        if (!map || !markers.home) return;

        homePosition = { lat, lon };

        // Update marker position
        markers.home.setLatLng([lat, lon]);

        // Add to map if not already added
        if (!map.hasLayer(markers.home)) {
            markers.home.addTo(map);
        }

        // Update tooltip
        markers.home.setTooltip(`Home: ${lat.toFixed(6)}, ${lon.toFixed(6)}`);
    }

    /**
     * Set Navigation Target
     */
    function setTarget(lat, lon) {
        if (!map || !markers.target) return;

        // Update marker position
        markers.target.setLatLng([lat, lon]);

        // Add to map if not already added
        if (!map.hasLayer(markers.target)) {
            markers.target.addTo(map);
        }

        // Update tooltip
        markers.target.setTooltip(`Target: ${lat.toFixed(6)}, ${lon.toFixed(6)}`);

        console.log(`Target set at: ${lat.toFixed(6)}, ${lon.toFixed(6)}`);
    }

    /**
     * Clear Navigation Target
     */
    function clearTarget() {
        if (map && markers.target && map.hasLayer(markers.target)) {
            map.removeLayer(markers.target);
        }
    }

    /**
     * Update Controls State
     */
    function updateControlsState() {
        if (elements.centerMapBtn) {
            elements.centerMapBtn.disabled = false; // Always enabled
        }

        if (elements.flyToToggle) {
            elements.flyToToggle.disabled = false; // Always enabled
        }

        if (elements.offlineMapsToggle) {
            elements.offlineMapsToggle.disabled = false; // Always enabled
        }
    }

    /**
     * Get Map Bounds
     */
    function getMapBounds() {
        if (!map) return null;

        const bounds = map.getBounds();
        return {
            north: bounds.getNorth(),
            south: bounds.getSouth(),
            east: bounds.getEast(),
            west: bounds.getWest(),
            zoom: map.getZoom()
        };
    }

    /**
     * Event Handlers
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail;

        // Update drone position
        if (data.lat && data.lon) {
            const heading = data.heading || 0;
            updateDronePosition(data.lat, data.lon, heading);
        }

        // Update home position if available
        if (data.home_lat && data.home_lon) {
            updateHomePosition(data.home_lat, data.home_lon);
        }
    }

    function handleConnectionChange(event) {
        isConnected = event.detail.connected;

        if (!isConnected) {
            // Hide markers on disconnect
            if (map && markers.drone && map.hasLayer(markers.drone)) {
                map.removeLayer(markers.drone);
            }
            if (map && markers.home && map.hasLayer(markers.home)) {
                map.removeLayer(markers.home);
            }
        }
    }

    /**
     * Handle Window Resize
     */
    function handleResize() {
        if (map) {
            // Trigger map resize
            setTimeout(() => {
                map.invalidateSize();
            }, 100);
        }
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,

        // Map control methods
        centerMap: centerMap,
        setTarget: setTarget,
        clearTarget: clearTarget,
        getMapBounds: getMapBounds,

        // State getters
        isFlyToActive: () => flyToMode,
        getCurrentPosition: () => ({ ...currentPosition }),
        getHomePosition: () => ({ ...homePosition }),
        getMap: () => map,

        // Module lifecycle callbacks
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: handleResize
    };
})();

/**
 * WebGCS Offline Maps Module
 * Handles map tile downloading and caching for offline operation
 */

window.OfflineMaps = (function() {
    'use strict';

    // Private variables
    let isDownloading = false;
    let downloadProgress = 0;
    let totalTiles = 0;
    let downloadedTiles = 0;
    let downloadAborted = false;
    let cacheStats = { street: 0, satellite: 0, total: 0 };

    // DOM elements
    let elements = {};

    // Download configuration
    const DOWNLOAD_CONFIG = {
        maxConcurrentRequests: 4,
        requestDelay: 100, // ms between requests
        retryAttempts: 3,
        tileSize: 256 // average tile size in bytes
    };

    /**
     * Initialize Offline Maps
     */
    function initialize() {
        console.log('Initializing Offline Maps...');

        // Cache DOM elements
        cacheElements();

        // Setup event listeners
        setupEventListeners();

        // Initialize UI state
        updateUIState();

        // Check internet connection
        checkInternetConnection();

        // Load cache statistics
        loadCacheStats();

        console.log('Offline Maps initialized');
    }

    /**
     * Cache DOM Elements
     */
    function cacheElements() {
        elements = {
            // Panel elements
            offlineMapsPanel: document.getElementById('offline-maps-panel'),
            closeOfflinePanel: document.getElementById('close-offline-panel'),
            internetStatus: document.getElementById('internet-status'),

            // Coordinate inputs
            northLat: document.getElementById('north-lat'),
            southLat: document.getElementById('south-lat'),
            westLon: document.getElementById('west-lon'),
            eastLon: document.getElementById('east-lon'),
            useCurrentView: document.getElementById('use-current-view'),

            // Zoom inputs
            minZoom: document.getElementById('min-zoom'),
            maxZoom: document.getElementById('max-zoom'),

            // Map type checkboxes
            downloadStreet: document.getElementById('download-street'),
            downloadSatellite: document.getElementById('download-satellite'),

            // Download info and controls
            estimatedTiles: document.getElementById('estimated-tiles'),
            estimatedSize: document.getElementById('estimated-size'),
            downloadTilesBtn: document.getElementById('download-tiles-btn'),
            stopDownloadBtn: document.getElementById('stop-download-btn'),

            // Progress elements
            downloadProgress: document.getElementById('download-progress'),
            progressFill: elements.downloadProgress?.querySelector('.progress-fill'),
            progressText: document.getElementById('progress-text'),

            // Cache statistics
            streetCount: document.getElementById('street-count'),
            satelliteCount: document.getElementById('satellite-count'),
            totalCount: document.getElementById('total-count'),
            clearCacheBtn: document.getElementById('clear-cache-btn')
        };

        // Fix progress fill reference
        if (elements.downloadProgress) {
            elements.progressFill = elements.downloadProgress.querySelector('.progress-fill');
        }

        // Check for missing elements
        Object.entries(elements).forEach(([key, element]) => {
            if (!element && key !== 'progressFill') {
                console.warn(`Offline Maps: Element '${key}' not found`);
            }
        });
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        // Close panel button
        if (elements.closeOfflinePanel) {
            elements.closeOfflinePanel.addEventListener('click', closePanel);
        }

        // Use current view button
        if (elements.useCurrentView) {
            elements.useCurrentView.addEventListener('click', useCurrentMapView);
        }

        // Download controls
        if (elements.downloadTilesBtn) {
            elements.downloadTilesBtn.addEventListener('click', startDownload);
        }

        if (elements.stopDownloadBtn) {
            elements.stopDownloadBtn.addEventListener('click', stopDownload);
        }

        // Clear cache button
        if (elements.clearCacheBtn) {
            elements.clearCacheBtn.addEventListener('click', clearCache);
        }

        // Input change listeners for estimation updates
        const estimationInputs = [
            elements.northLat, elements.southLat, elements.westLon, elements.eastLon,
            elements.minZoom, elements.maxZoom, elements.downloadStreet, elements.downloadSatellite
        ];

        estimationInputs.forEach(input => {
            if (input) {
                input.addEventListener('input', updateDownloadEstimation);
                input.addEventListener('change', updateDownloadEstimation);
            }
        });

        // Internet connection monitoring
        window.addEventListener('online', () => checkInternetConnection());
        window.addEventListener('offline', () => checkInternetConnection());

        // Periodic connection check
        setInterval(checkInternetConnection, 30000); // Every 30 seconds
    }

    /**
     * Close Offline Maps Panel
     */
    function closePanel() {
        if (elements.offlineMapsPanel) {
            elements.offlineMapsPanel.classList.remove('active');
        }
    }

    /**
     * Use Current Map View
     */
    function useCurrentMapView() {
        if (window.WebGCS?.modules?.MapController?.getMapBounds) {
            const bounds = window.WebGCS.modules.MapController.getMapBounds();

            if (bounds) {
                if (elements.northLat) elements.northLat.value = bounds.north.toFixed(6);
                if (elements.southLat) elements.southLat.value = bounds.south.toFixed(6);
                if (elements.westLon) elements.westLon.value = bounds.west.toFixed(6);
                if (elements.eastLon) elements.eastLon.value = bounds.east.toFixed(6);

                // Update zoom to current zoom level
                if (elements.maxZoom) elements.maxZoom.value = Math.min(bounds.zoom + 2, 20);

                updateDownloadEstimation();
                window.WebGCS?.showMessage('Download area set to current map view', 'info');
            }
        } else {
            window.WebGCS?.showMessage('Map controller not available', 'error');
        }
    }

    /**
     * Update Download Estimation
     */
    function updateDownloadEstimation() {
        const coords = getDownloadCoordinates();
        const zooms = getZoomRange();
        const mapTypes = getSelectedMapTypes();

        if (!coords || !zooms || mapTypes.length === 0) {
            updateEstimationDisplay(0, 0);
            return;
        }

        const tiles = estimateTileCount(coords, zooms, mapTypes);
        const sizeBytes = tiles * DOWNLOAD_CONFIG.tileSize;
        const sizeMB = sizeBytes / (1024 * 1024);

        updateEstimationDisplay(tiles, sizeMB);
    }

    /**
     * Estimate Tile Count
     */
    function estimateTileCount(coords, zooms, mapTypes) {
        let totalTiles = 0;

        for (let zoom = zooms.min; zoom <= zooms.max; zoom++) {
            const tilesForZoom = calculateTilesForZoom(coords, zoom);
            totalTiles += tilesForZoom * mapTypes.length;
        }

        return totalTiles;
    }

    /**
     * Calculate Tiles for Zoom Level
     */
    function calculateTilesForZoom(coords, zoom) {
        const tileSize = 256;
        const n = Math.pow(2, zoom);

        // Convert lat/lon to tile coordinates
        const minTileX = Math.floor((coords.west + 180) / 360 * n);
        const maxTileX = Math.floor((coords.east + 180) / 360 * n);
        const minTileY = Math.floor((1 - Math.log(Math.tan(coords.north * Math.PI / 180) + 1 / Math.cos(coords.north * Math.PI / 180)) / Math.PI) / 2 * n);
        const maxTileY = Math.floor((1 - Math.log(Math.tan(coords.south * Math.PI / 180) + 1 / Math.cos(coords.south * Math.PI / 180)) / Math.PI) / 2 * n);

        const tilesX = Math.abs(maxTileX - minTileX) + 1;
        const tilesY = Math.abs(maxTileY - minTileY) + 1;

        return tilesX * tilesY;
    }

    /**
     * Update Estimation Display
     */
    function updateEstimationDisplay(tiles, sizeMB) {
        if (elements.estimatedTiles) {
            elements.estimatedTiles.textContent = tiles.toLocaleString();
        }

        if (elements.estimatedSize) {
            elements.estimatedSize.textContent = sizeMB.toFixed(1);
        }

        // Enable/disable download button based on estimation
        if (elements.downloadTilesBtn) {
            elements.downloadTilesBtn.disabled = tiles === 0 || tiles > 50000; // Reasonable limit
        }
    }

    /**
     * Start Download Process
     */
    function startDownload() {
        const coords = getDownloadCoordinates();
        const zooms = getZoomRange();
        const mapTypes = getSelectedMapTypes();

        if (!coords || !zooms || mapTypes.length === 0) {
            window.WebGCS?.showMessage('Please configure download parameters', 'error');
            return;
        }

        // Estimate total tiles
        totalTiles = estimateTileCount(coords, zooms, mapTypes);

        if (totalTiles > 50000) {
            window.WebGCS?.showMessage('Download area too large. Please reduce area or zoom levels.', 'error');
            return;
        }

        if (totalTiles === 0) {
            window.WebGCS?.showMessage('No tiles to download', 'warning');
            return;
        }

        // Confirm download
        const message = `Download ${totalTiles.toLocaleString()} tiles?\nThis may take several minutes.`;

        if (window.WebGCS?.showConfirmation) {
            window.WebGCS.showConfirmation('Start Download', message, (confirmed) => {
                if (confirmed) {
                    executeDownload(coords, zooms, mapTypes);
                }
            });
        } else {
            if (confirm(message)) {
                executeDownload(coords, zooms, mapTypes);
            }
        }
    }

    /**
     * Execute Download
     */
    async function executeDownload(coords, zooms, mapTypes) {
        console.log('Starting tile download...', { coords, zooms, mapTypes, totalTiles });

        // Set download state
        isDownloading = true;
        downloadedTiles = 0;
        downloadAborted = false;
        downloadProgress = 0;

        // Update UI
        updateDownloadUI(true);
        updateProgressDisplay(0, 'Starting download...');

        try {
            // Generate tile list
            const tileList = generateTileList(coords, zooms, mapTypes);

            // Download tiles in batches
            await downloadTileBatches(tileList);

            if (!downloadAborted) {
                updateProgressDisplay(100, 'Download completed!');
                window.WebGCS?.showMessage(`Downloaded ${downloadedTiles} tiles successfully`, 'success');

                // Update cache statistics
                loadCacheStats();
            }

        } catch (error) {
            console.error('Download failed:', error);
            updateProgressDisplay(downloadProgress, `Download failed: ${error.message}`);
            window.WebGCS?.showMessage(`Download failed: ${error.message}`, 'error');
        } finally {
            // Reset download state
            isDownloading = false;
            updateDownloadUI(false);
        }
    }

    /**
     * Generate Tile List
     */
    function generateTileList(coords, zooms, mapTypes) {
        const tiles = [];

        mapTypes.forEach(mapType => {
            for (let zoom = zooms.min; zoom <= zooms.max; zoom++) {
                const tilesForZoom = generateTilesForZoom(coords, zoom, mapType);
                tiles.push(...tilesForZoom);
            }
        });

        return tiles;
    }

    /**
     * Generate Tiles for Zoom Level
     */
    function generateTilesForZoom(coords, zoom, mapType) {
        const tiles = [];
        const n = Math.pow(2, zoom);

        const minTileX = Math.floor((coords.west + 180) / 360 * n);
        const maxTileX = Math.floor((coords.east + 180) / 360 * n);
        const minTileY = Math.floor((1 - Math.log(Math.tan(coords.north * Math.PI / 180) + 1 / Math.cos(coords.north * Math.PI / 180)) / Math.PI) / 2 * n);
        const maxTileY = Math.floor((1 - Math.log(Math.tan(coords.south * Math.PI / 180) + 1 / Math.cos(coords.south * Math.PI / 180)) / Math.PI) / 2 * n);

        for (let x = minTileX; x <= maxTileX; x++) {
            for (let y = minTileY; y <= maxTileY; y++) {
                tiles.push({
                    x, y, z: zoom, mapType,
                    url: getTileUrl(x, y, zoom, mapType)
                });
            }
        }

        return tiles;
    }

    /**
     * Get Tile URL
     */
    function getTileUrl(x, y, z, mapType) {
        if (mapType === 'street') {
            return `https://tile.openstreetmap.org/${z}/${x}/${y}.png`;
        } else if (mapType === 'satellite') {
            return `https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/${z}/${y}/${x}`;
        }
        return null;
    }

    /**
     * Download Tile Batches
     */
    async function downloadTileBatches(tileList) {
        const batchSize = DOWNLOAD_CONFIG.maxConcurrentRequests;

        for (let i = 0; i < tileList.length; i += batchSize) {
            if (downloadAborted) break;

            const batch = tileList.slice(i, i + batchSize);
            const downloadPromises = batch.map(tile => downloadTile(tile));

            try {
                await Promise.allSettled(downloadPromises);
            } catch (error) {
                console.warn('Batch download error:', error);
            }

            // Update progress
            downloadProgress = Math.min((downloadedTiles / totalTiles) * 100, 100);
            updateProgressDisplay(downloadProgress, `Downloaded ${downloadedTiles}/${totalTiles} tiles`);

            // Add delay between batches
            if (!downloadAborted && i + batchSize < tileList.length) {
                await new Promise(resolve => setTimeout(resolve, DOWNLOAD_CONFIG.requestDelay));
            }
        }
    }

    /**
     * Download Single Tile
     */
    async function downloadTile(tile) {
        if (downloadAborted) return;

        let attempts = 0;
        while (attempts < DOWNLOAD_CONFIG.retryAttempts) {
            try {
                const response = await fetch(tile.url);
                if (response.ok) {
                    const blob = await response.blob();

                    // Store tile in IndexedDB cache
                    await cacheTile(tile, blob);

                    downloadedTiles++;
                    return;
                }
            } catch (error) {
                attempts++;
                if (attempts >= DOWNLOAD_CONFIG.retryAttempts) {
                    console.warn(`Failed to download tile after ${attempts} attempts:`, tile, error);
                }
            }
        }
    }

    /**
     * Cache Tile in IndexedDB
     */
    async function cacheTile(tile, blob) {
        // This would typically use IndexedDB
        // For now, we'll simulate caching
        const cacheKey = `tile_${tile.mapType}_${tile.z}_${tile.x}_${tile.y}`;

        try {
            // Simulate cache storage
            if (typeof(Storage) !== "undefined") {
                // Convert blob to base64 for localStorage simulation
                const base64 = await blobToBase64(blob);
                localStorage.setItem(cacheKey, JSON.stringify({
                    data: base64,
                    timestamp: Date.now(),
                    mapType: tile.mapType,
                    z: tile.z, x: tile.x, y: tile.y
                }));
            }
        } catch (error) {
            console.warn('Failed to cache tile:', cacheKey, error);
        }
    }

    /**
     * Convert Blob to Base64
     */
    function blobToBase64(blob) {
        return new Promise((resolve, reject) => {
            const reader = new FileReader();
            reader.onload = () => resolve(reader.result);
            reader.onerror = reject;
            reader.readAsDataURL(blob);
        });
    }

    /**
     * Stop Download
     */
    function stopDownload() {
        if (isDownloading) {
            downloadAborted = true;
            updateProgressDisplay(downloadProgress, 'Download stopped');
            window.WebGCS?.showMessage('Download stopped by user', 'info');
        }
    }

    /**
     * Clear Cache
     */
    function clearCache() {
        const message = 'This will delete all cached map tiles. Continue?';

        if (window.WebGCS?.showConfirmation) {
            window.WebGCS.showConfirmation('Clear Cache', message, (confirmed) => {
                if (confirmed) {
                    executeClearCache();
                }
            });
        } else {
            if (confirm(message)) {
                executeClearCache();
            }
        }
    }

    /**
     * Execute Clear Cache
     */
    function executeClearCache() {
        try {
            // Clear tile cache from localStorage (simulation)
            const keys = Object.keys(localStorage);
            let cleared = 0;

            keys.forEach(key => {
                if (key.startsWith('tile_')) {
                    localStorage.removeItem(key);
                    cleared++;
                }
            });

            // Reset cache stats
            cacheStats = { street: 0, satellite: 0, total: 0 };
            updateCacheStatsDisplay();

            window.WebGCS?.showMessage(`Cleared ${cleared} cached tiles`, 'success');
        } catch (error) {
            console.error('Cache clear failed:', error);
            window.WebGCS?.showMessage('Cache clear failed', 'error');
        }
    }

    /**
     * Load Cache Statistics
     */
    function loadCacheStats() {
        try {
            const keys = Object.keys(localStorage);
            cacheStats = { street: 0, satellite: 0, total: 0 };

            keys.forEach(key => {
                if (key.startsWith('tile_')) {
                    const data = JSON.parse(localStorage.getItem(key) || '{}');
                    if (data.mapType === 'street') {
                        cacheStats.street++;
                    } else if (data.mapType === 'satellite') {
                        cacheStats.satellite++;
                    }
                    cacheStats.total++;
                }
            });

            updateCacheStatsDisplay();
        } catch (error) {
            console.warn('Failed to load cache stats:', error);
        }
    }

    /**
     * Update Cache Statistics Display
     */
    function updateCacheStatsDisplay() {
        if (elements.streetCount) {
            elements.streetCount.textContent = cacheStats.street.toLocaleString();
        }
        if (elements.satelliteCount) {
            elements.satelliteCount.textContent = cacheStats.satellite.toLocaleString();
        }
        if (elements.totalCount) {
            elements.totalCount.textContent = cacheStats.total.toLocaleString();
        }
    }

    /**
     * Update Progress Display
     */
    function updateProgressDisplay(percent, text) {
        if (elements.progressFill) {
            elements.progressFill.style.width = `${percent}%`;
        }
        if (elements.progressText) {
            elements.progressText.textContent = text;
        }
    }

    /**
     * Update Download UI State
     */
    function updateDownloadUI(downloading) {
        if (elements.downloadTilesBtn) {
            elements.downloadTilesBtn.disabled = downloading;
            elements.downloadTilesBtn.textContent = downloading ? 'Downloading...' : 'Download Tiles';
        }

        if (elements.stopDownloadBtn) {
            elements.stopDownloadBtn.disabled = !downloading;
        }
    }

    /**
     * Update UI State
     */
    function updateUIState() {
        updateDownloadEstimation();
        updateDownloadUI(false);
    }

    /**
     * Check Internet Connection
     */
    function checkInternetConnection() {
        const online = navigator.onLine;

        if (elements.internetStatus) {
            const indicator = elements.internetStatus.querySelector('.status-indicator');
            const text = elements.internetStatus.querySelector('.status-text');

            if (online) {
                elements.internetStatus.className = 'internet-status online';
                if (indicator) indicator.textContent = '🌐';
                if (text) text.textContent = 'Online';
            } else {
                elements.internetStatus.className = 'internet-status offline';
                if (indicator) indicator.textContent = '📡';
                if (text) text.textContent = 'Offline';
            }
        }
    }

    /**
     * Helper Functions
     */
    function getDownloadCoordinates() {
        const north = parseFloat(elements.northLat?.value);
        const south = parseFloat(elements.southLat?.value);
        const west = parseFloat(elements.westLon?.value);
        const east = parseFloat(elements.eastLon?.value);

        if (isNaN(north) || isNaN(south) || isNaN(west) || isNaN(east)) {
            return null;
        }

        return { north, south, west, east };
    }

    function getZoomRange() {
        const min = parseInt(elements.minZoom?.value) || 2;
        const max = parseInt(elements.maxZoom?.value) || 16;

        if (min > max) return null;

        return { min, max };
    }

    function getSelectedMapTypes() {
        const types = [];
        if (elements.downloadStreet?.checked) types.push('street');
        if (elements.downloadSatellite?.checked) types.push('satellite');
        return types;
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,

        // Update methods for external use
        updateCurrentMapView: (bounds, zoom) => {
            // This is called by MapController when map view changes
            // Could be used to auto-update download area
        },

        // State getters
        isDownloading: () => isDownloading,
        getCacheStats: () => ({ ...cacheStats }),

        // Module lifecycle callbacks
        onResize: () => {
            // Handle responsive layout changes if needed
        }
    };
})();

/**
 * WebGCS Audio Manager Module
 * Handles voice announcements and audio feedback
 */

window.AudioManager = (function() {
    'use strict';

    // Private variables
    let audioContext = null;
    let voiceEnabled = false;
    let speechSynthesis = null;
    let currentVoice = null;
    let lastAnnouncement = '';
    let announcementQueue = [];
    let isPlaying = false;

    // DOM elements
    let elements = {};

    // Audio configuration
    const AUDIO_CONFIG = {
        heartbeatFreq: 800,    // Hz
        heartbeatDuration: 0.1, // seconds
        voiceRate: 1.0,        // Speech rate
        voicePitch: 1.0,       // Speech pitch
        voiceVolume: 0.8,      // Speech volume
        maxQueueSize: 5        // Maximum queued announcements
    };

    /**
     * Initialize Audio Manager
     */
    function initialize() {
        console.log('Initializing Audio Manager...');

        // Cache DOM elements
        cacheElements();

        // Initialize audio systems
        initializeAudioContext();
        initializeSpeechSynthesis();

        // Setup event listeners
        setupEventListeners();

        // Load saved preferences
        loadPreferences();

        console.log('Audio Manager initialized');
    }

    /**
     * Cache DOM Elements
     */
    function cacheElements() {
        elements = {
            voiceAnnouncements: document.getElementById('voice-announcements'),
            heartbeatSound: document.getElementById('heartbeat-sound')
        };

        // Check for missing elements
        Object.entries(elements).forEach(([key, element]) => {
            if (!element) {
                console.warn(`Audio Manager: Element '${key}' not found`);
            }
        });
    }

    /**
     * Initialize Web Audio Context
     */
    function initializeAudioContext() {
        try {
            audioContext = new (window.AudioContext || window.webkitAudioContext)();
            console.log('Web Audio Context initialized');
        } catch (error) {
            console.warn('Web Audio Context not supported:', error);
        }
    }

    /**
     * Initialize Speech Synthesis
     */
    function initializeSpeechSynthesis() {
        if ('speechSynthesis' in window) {
            speechSynthesis = window.speechSynthesis;

            // Wait for voices to load
            const loadVoices = () => {
                const voices = speechSynthesis.getVoices();
                if (voices.length > 0) {
                    // Prefer English voices
                    currentVoice = voices.find(voice => voice.lang.startsWith('en')) || voices[0];
                    console.log('Speech synthesis initialized with voice:', currentVoice.name);
                } else {
                    // Retry after a delay
                    setTimeout(loadVoices, 100);
                }
            };

            speechSynthesis.onvoiceschanged = loadVoices;
            loadVoices();

        } else {
            console.warn('Speech synthesis not supported');
        }
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        // Voice announcements toggle
        if (elements.voiceAnnouncements) {
            elements.voiceAnnouncements.addEventListener('change', handleVoiceToggle);
        }

        // Listen for global events
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
            window.WebGCS.eventBus.addEventListener('command_result', handleCommandResult);
        }

        // Handle audio context resume (required by browsers)
        document.addEventListener('click', resumeAudioContext, { once: true });
        document.addEventListener('keydown', resumeAudioContext, { once: true });
    }

    /**
     * Resume Audio Context
     */
    function resumeAudioContext() {
        if (audioContext && audioContext.state === 'suspended') {
            audioContext.resume().then(() => {
                console.log('Audio context resumed');
            }).catch(error => {
                console.warn('Failed to resume audio context:', error);
            });
        }
    }

    /**
     * Handle Voice Toggle
     */
    function handleVoiceToggle(event) {
        voiceEnabled = event.target.checked;

        console.log('Voice announcements:', voiceEnabled ? 'enabled' : 'disabled');

        // Save preference
        localStorage.setItem('webgcs_voice_enabled', voiceEnabled.toString());

        // Announce the change
        if (voiceEnabled) {
            announceText('Voice announcements enabled');
        }

        // Resume audio context if enabling voice
        if (voiceEnabled) {
            resumeAudioContext();
        }
    }

    /**
     * Play Heartbeat Sound
     */
    function playHeartbeatSound() {
        if (!audioContext) return;

        try {
            const oscillator = audioContext.createOscillator();
            const gainNode = audioContext.createGain();

            oscillator.connect(gainNode);
            gainNode.connect(audioContext.destination);

            oscillator.frequency.setValueAtTime(AUDIO_CONFIG.heartbeatFreq, audioContext.currentTime);
            gainNode.gain.setValueAtTime(0, audioContext.currentTime);
            gainNode.gain.linearRampToValueAtTime(0.1, audioContext.currentTime + 0.01);
            gainNode.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + AUDIO_CONFIG.heartbeatDuration);

            oscillator.start(audioContext.currentTime);
            oscillator.stop(audioContext.currentTime + AUDIO_CONFIG.heartbeatDuration);

        } catch (error) {
            console.warn('Could not play heartbeat sound:', error);
        }
    }

    /**
     * Announce Text via Speech Synthesis
     */
    function announceText(text, priority = false) {
        if (!voiceEnabled || !speechSynthesis || !currentVoice) return;

        // Avoid duplicate announcements
        if (text === lastAnnouncement && !priority) {
            return;
        }

        // Manage announcement queue
        if (priority) {
            // Clear queue for priority announcements
            announcementQueue = [];
            speechSynthesis.cancel();
        } else if (announcementQueue.length >= AUDIO_CONFIG.maxQueueSize) {
            console.log('Announcement queue full, skipping:', text);
            return;
        }

        // Add to queue
        announcementQueue.push(text);
        lastAnnouncement = text;

        // Process queue if not already playing
        if (!isPlaying) {
            processAnnouncementQueue();
        }
    }

    /**
     * Process Announcement Queue
     */
    function processAnnouncementQueue() {
        if (announcementQueue.length === 0) {
            isPlaying = false;
            return;
        }

        isPlaying = true;
        const text = announcementQueue.shift();

        const utterance = new SpeechSynthesisUtterance(text);
        utterance.voice = currentVoice;
        utterance.rate = AUDIO_CONFIG.voiceRate;
        utterance.pitch = AUDIO_CONFIG.voicePitch;
        utterance.volume = AUDIO_CONFIG.voiceVolume;

        utterance.onend = () => {
            console.log('Announcement completed:', text);
            // Process next in queue
            setTimeout(() => processAnnouncementQueue(), 500);
        };

        utterance.onerror = (error) => {
            console.warn('Speech synthesis error:', error);
            // Continue with queue
            setTimeout(() => processAnnouncementQueue(), 500);
        };

        try {
            speechSynthesis.speak(utterance);
            console.log('Announcing:', text);
        } catch (error) {
            console.warn('Failed to announce:', text, error);
            setTimeout(() => processAnnouncementQueue(), 500);
        }
    }

    /**
     * Announce Connection Status
     */
    function announceConnectionStatus(connected) {
        const status = connected ? 'Drone connected' : 'Drone disconnected';
        announceText(status, true);
    }

    /**
     * Announce Arm Status
     */
    function announceArmStatus(armed) {
        const status = armed ? 'Vehicle armed' : 'Vehicle disarmed';
        announceText(status, true);
    }

    /**
     * Announce Mode Change
     */
    function announceModeChange(mode) {
        announceText(`Flight mode ${mode}`);
    }

    /**
     * Announce Battery Status
     */
    function announceBatteryStatus(voltage) {
        if (voltage < 11.0) {
            announceText(`Low battery warning: ${voltage.toFixed(1)} volts`, true);
        } else if (voltage < 11.5) {
            announceText(`Battery low: ${voltage.toFixed(1)} volts`);
        }
    }

    /**
     * Announce GPS Status
     */
    function announceGPSStatus(fixType, satellites) {
        if (fixType >= 3 && satellites >= 6) {
            // Good GPS fix
            announceText('GPS fix acquired');
        } else if (fixType < 2) {
            // No GPS fix
            announceText('GPS fix lost', true);
        }
    }

    /**
     * Announce Command Result
     */
    function announceCommandResult(command, success, error = null) {
        if (success) {
            switch (command) {
                case 'arm':
                    announceText('Arm command successful');
                    break;
                case 'disarm':
                    announceText('Disarm command successful');
                    break;
                case 'takeoff':
                    announceText('Takeoff command successful');
                    break;
                case 'land':
                    announceText('Landing command successful');
                    break;
                case 'rtl':
                    announceText('Return to launch initiated');
                    break;
                case 'goto':
                    announceText('Navigation command sent');
                    break;
                default:
                    announceText(`${command} command successful`);
            }
        } else {
            announceText(`${command} command failed`, true);
        }
    }

    /**
     * Create Audio Beep
     */
    function playBeep(frequency = 1000, duration = 0.2, volume = 0.1) {
        if (!audioContext) return;

        try {
            const oscillator = audioContext.createOscillator();
            const gainNode = audioContext.createGain();

            oscillator.connect(gainNode);
            gainNode.connect(audioContext.destination);

            oscillator.frequency.setValueAtTime(frequency, audioContext.currentTime);
            gainNode.gain.setValueAtTime(0, audioContext.currentTime);
            gainNode.gain.linearRampToValueAtTime(volume, audioContext.currentTime + 0.01);
            gainNode.gain.exponentialRampToValueAtTime(0.001, audioContext.currentTime + duration);

            oscillator.start(audioContext.currentTime);
            oscillator.stop(audioContext.currentTime + duration);

        } catch (error) {
            console.warn('Could not play beep:', error);
        }
    }

    /**
     * Load Saved Preferences
     */
    function loadPreferences() {
        // Load voice enabled preference
        const voiceSaved = localStorage.getItem('webgcs_voice_enabled');
        if (voiceSaved !== null) {
            voiceEnabled = voiceSaved === 'true';
            if (elements.voiceAnnouncements) {
                elements.voiceAnnouncements.checked = voiceEnabled;
            }
        }
    }

    /**
     * Event Handlers
     */
    let lastBatteryWarning = 0;
    let lastGPSStatus = -1;

    function handleTelemetryUpdate(event) {
        const data = event.detail;

        // Battery monitoring
        if (data.battery_voltage && data.battery_voltage > 0) {
            const now = Date.now();
            if (now - lastBatteryWarning > 60000) { // Once per minute
                if (data.battery_voltage < 11.0) {
                    announceBatteryStatus(data.battery_voltage);
                    lastBatteryWarning = now;
                }
            }
        }

        // GPS status monitoring
        if (data.gps_fix_type !== undefined && data.gps_fix_type !== lastGPSStatus) {
            announceGPSStatus(data.gps_fix_type, data.satellites_visible || 0);
            lastGPSStatus = data.gps_fix_type;
        }
    }

    function handleConnectionChange(event) {
        announceConnectionStatus(event.detail.connected);
    }

    function handleCommandResult(event) {
        const result = event.detail;
        announceCommandResult(result.command, result.success, result.error);
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,

        // Audio methods
        playHeartbeatSound: playHeartbeatSound,
        playBeep: playBeep,
        announceText: announceText,

        // Specific announcements
        announceConnectionStatus: announceConnectionStatus,
        announceArmStatus: announceArmStatus,
        announceModeChange: announceModeChange,
        announceBatteryStatus: announceBatteryStatus,
        announceGPSStatus: announceGPSStatus,
        announceCommandResult: announceCommandResult,

        // State getters
        isVoiceEnabled: () => voiceEnabled,
        isAudioContextReady: () => audioContext && audioContext.state === 'running',

        // Heartbeat callback for connection manager
        onHeartbeat: playHeartbeatSound,

        // Module lifecycle callbacks
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: () => {
            // Handle responsive layout changes if needed
        }
    };
})();

